example_after.code:
useEffect(() => {
  setCount(prev => prev + 1);
}, []); // Boş bağımlılık dizisi

example_before.code:
const handleClick = () => {
  setState(prev => prev + 1);
};

useEffect(() => {
  // handleClick her render'da yeni bir fonksiyon
}, [handleClick]);

example_after.code:
const handleClick = useCallback(() => {
  setState(prev => prev + 1);
}, []);

useEffect(() => {
  // handleClick stabil bir referans
}, [handleClick]);

example_before.code:
const Parent = () => {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    console.log('clicked');
  };

  return <Child onClick={handleClick} />;
};

example_after.code:
const Parent = () => {
  const [count, setCount] = useState(0);

  const handleClick = useCallback(() => {
    console.log('clicked');
  }, []); // Boş bağımlılık dizisi

  return <Child onClick={handleClick} />;
};

example_before.code:
const Parent = () => {
  const data = expensiveCalculation(props.items);
  return <Child data={data} />;
};

example_after.code:
const Parent = () => {
  const data = useMemo(() => {
    return expensiveCalculation(props.items);
  }, [props.items]);
  return <Child data={data} />;
};

example_before.code:
const Child = ({ value, onClick }) => {
  console.log('Child rendered');
  return <Text onPress={onClick}>{value}</Text>;
};

example_after.code:
const Child = React.memo(({ value, onClick }) => {
  console.log('Child rendered');
  return <Text onPress={onClick}>{value}</Text>;
});

example_before.code:
const loadData = async () => {
  const data = fetchData(); // await eksik
  console.log(data); // undefined
};

example_after.code:
const loadData = async () => {
  const data = await fetchData(); // await eklendi
  console.log(data); // doğru veri
};

example_before.code:
const loadData = async () => {
  const data = await fetchData();
  return data;
};

example_after.code:
const loadData = async () => {
  try {
    const data = await fetchData();
    return data;
  } catch (error) {
    console.error('Error loading data:', error);
    return null;
  }
};

example_before.code:
const [count, setCount] = useState(0);

const increment = () => {
  setCount(count + 1); // Eski değer kullanılıyor
  setCount(count + 1); // Aynı eski değer
  // Sonuç: count + 1 (beklenen: count + 2)
};

example_after.code:
const [count, setCount] = useState(0);

const increment = () => {
  setCount(prev => prev + 1); // Previous state kullanılıyor
  setCount(prev => prev + 1); // Güncellenmiş değer
  // Sonuç: count + 2 (doğru)
};

example_before.code:
const [data, setData] = useState(null);

useEffect(() => {
  fetchData().then(result => {
    setData(result);
    console.log(data); // null (state henüz güncellenmedi)
  });
}, []);

example_after.code:
const [data, setData] = useState(null);

useEffect(() => {
  fetchData().then(result => {
    setData(result);
    console.log(result); // Doğru veri
  });
}, []);

example_before.code:
interface User {
  name: string;
  age: number;
}

const user: User = {
  name: 'John',
  age: '25' // Hata: string, number bekleniyor
};

example_after.code:
interface User {
  name: string;
  age: number;
}

const user: User = {
  name: 'John',
  age: 25 // Düzeltildi: number
};

example_before.code:
interface User {
  name: string;
  age: number;
  email: string; // Her zaman gerekli
}

const user: User = {
  name: 'John',
  age: 25
  // Hata: email eksik
};

example_after.code:
interface User {
  name: string;
  age: number;
  email?: string; // Opsiyonel
}

const user: User = {
  name: 'John',
  age: 25
  // Hata yok
};

example_before.code:
interface User {
  name: string;
  age: number;
}

const user: User = { name: 'John', age: 25 };
console.log(user.email); // Hata: email mevcut değil

example_after.code:
interface User {
  name: string;
  age: number;
  email?: string; // Özellik eklendi
}

const user: User = { name: 'John', age: 25 };
console.log(user.email); // Hata yok (undefined döner)

example_before.code:
interface User {
  name: string;
  email?: string;
}

function sendEmail(user: User) {
  console.log(user.email.toLowerCase()); // Hata: email undefined olabilir
}

example_after.code:
interface User {
  name: string;
  email?: string;
}

function sendEmail(user: User) {
  if (user.email) {
    console.log(user.email.toLowerCase()); // Güvenli
  }
}
